BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP104-1-15','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考消除對婦女一切形式歧視公約施行法第2條（公約具國內法律之效力）、第6條（每四年提出國家報告）、第7條（經費依財政狀況優先編列）及第8條（施行後三年內完成法規及行政措施之檢討改進）。本法 2011-06-08 制定公布、2012-01-01 施行後未曾修正，考試時條文與現行條文相同，選項(B)「每2年」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050175'),('SP104-1-17','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考身心障礙者權利公約施行法（全文12條）第2條（公約具國內法律之效力）、第6條（推動小組之學者專家、身心障礙團體不得少於總數二分之一，任一性別不得少於三分之一）、第7條（施行後二年提出初次國家報告，之後每四年提出）及第10條（施行後二年內提出優先檢視清單）。本法 2014-08-20 制定公布、2014-12-03 施行後未曾修正，考試時條文與現行條文相同，選項(C)「每5年」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SP104-2-09','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。本題考人權公約施行法之共通規定，以兒童權利公約施行法第3條、第5條、第7條、第8條及消除對婦女一切形式歧視公約施行法第3條、第5條、第6條、第7條為例：各級政府機關相互協調並與國際合作推動執行、定期提出國家報告並邀請專家學者及民間團體代表審閱、經費依財政狀況優先編列逐步實施；適用公約規定之法規及行政措施應參照公約意旨及聯合國相關委員會之解釋，並非「依據公約內容加以訂定」。上開條文考試日後均未修正，選項(D)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SP104-2-10','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。本題考我國已制定施行法之聯合國權利公約：消除對婦女一切形式歧視公約施行法（2011-06-08）、兒童權利公約施行法（2014-06-04）、身心障礙者權利公約施行法（2014-08-20）均已制定公布，各法第2條規定公約具國內法律之效力，考試日後持續施行；聯合國迄未通過「老人權利公約」，我國亦無其施行法，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SP105-1-21','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考身心障礙者權利公約施行法第6條（身心障礙者權益推動小組之學者專家、身心障礙團體（機構）不得少於總數二分之一，任一性別不得少於三分之一）。本法 2014-08-20 制定公布、2014-12-03 施行後未曾修正，考試時條文與現行條文相同，選項(A)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SP106-1-09','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考民法第1055條第1項（夫妻離婚者，對於未成年子女權利義務之行使或負擔，依協議由一方或雙方共同任之）與兒童權利公約第12條（兒童表意權）之關係。民法第1055條最後修正公布日 1996-09-25，考試日後未再修正；公約本文亦未修正，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SP106-1-21','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考我國以施行法將國際公約國內法化之情形：身心障礙者權利公約施行法（2014-08-20）、消除對婦女一切形式歧視公約施行法（2011-06-08）及聯合國反貪腐公約施行法均已制定，前二法第2條規定公約具國內法律之效力；「聯合國老人綱領」為聯合國大會決議通過之原則，並非公約，我國未制定施行法，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SP106-2-05','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考兒童權利公約施行法第7條（施行後二年內提出第一次國家報告，其後每五年提出）、第10條（自 2014-11-20 施行，全文10條）、兒童權利公約之一般性原則，以及民法第1059條（父母未約定或約定不成子女姓氏者，於戶政事務所抽籤決定，並非從父姓）。上開施行法條文及民法第1059條（最後修正公布日 2010-05-19）考試日後均未再修正，選項(B)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SP106-2-06','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題比較三部人權公約施行法：消除對婦女一切形式歧視公約施行法於 2011-06-08 制定公布（最早），兒童權利公約施行法於 2014-06-04、身心障礙者權利公約施行法於 2014-08-20 制定公布；三法第2條均規定公約具國內法律之效力；國家報告週期分別為每四年（消除對婦女一切形式歧視公約施行法第6條）、每五年（兒童權利公約施行法第7條）及每四年（身心障礙者權利公約施行法第7條）；消除對婦女一切形式歧視公約施行法未設推動小組，身心障礙者權利公約施行法第6條及兒童權利公約施行法第6條（2019-06-19 修正）均規定小組成員任一性別不得少於三分之一。除兒童權利公約施行法第6條外，上開條文考試日後均未修正，且該條修正後仍為三分之一，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SP107-1-23','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考身心障礙者權利公約施行法第2條、第7條（施行後二年提出初次國家報告，之後每四年）、第9條（經費優先編列，逐步實施）及第10條（施行後二年內提出優先檢視清單、三年內完成增修廢止、五年內完成其餘法規）。本法施行後未曾修正，考試時條文與現行條文相同，選項(D)「四年內完成其餘法規」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SP107-1-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考公民與政治權利國際公約及經濟社會文化權利國際公約施行法第2條（兩公約具國內法律之效力）及第8條（不符兩公約之法令及行政措施，應於施行後二年內完成檢討改進），本法 2009-04-22 制定公布、2009-12-10 施行後未曾修正，選項(D)「3年內」仍錯誤；其餘選項為兩公約通過年份及國際人權憲章之史實。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=I0020028'),('SP107-1-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考兒童權利公約之四項一般性原則（第2條禁止歧視、第3條兒童最佳利益、第6條生命權、生存及發展權、第12條尊重兒童意見），屬公約本文及聯合國兒童權利委員會之解釋，公約前開條文未經修正；兒童權利公約施行法第2條（公約具國內法律之效力）自 2014-11-20 施行後亦未修正，選項(D)「福利與受教權」仍非一般性原則。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SP108-2-09','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考消除對婦女一切形式歧視公約及消除對婦女一切形式歧視公約施行法：施行法 2011-06-08 制定公布、依第9條自 2012-01-01 施行，第6條規定每四年提出國家報告；施行法公布後未曾修正，選項(D)「每5年」仍錯誤，其餘選項為公約通過與我國加入之史實。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050175'),('SP109-1-06','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-02-15。本題考我國以施行法將國際公約國內法化之情形：身心障礙者權利公約施行法、消除對婦女一切形式歧視公約施行法及兒童權利公約施行法均已制定（各法第2條規定公約具國內法律之效力）；保護所有移徙工人及其家庭成員權利國際公約之施行法迄未通過（國家人權委員會資料；勞動部於 2024 年撤回送審案），選項(D)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SP115-1-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-02-07。本題考兒童權利公約第1條（兒童指未滿十八歲之人）及兒童權利公約之四項一般性原則（第2條禁止歧視、第3條兒童最佳利益、第6條生命權、生存及發展權、第12條尊重兒童意見），並涉及聯合國 1976 年決議將 1979 年訂為國際兒童年之史實；屬公約本文及聯合國兒童權利委員會之解釋，公約前開條文未經修正；兒童權利公約施行法第2條（公約具國內法律之效力）自 2014-11-20 施行後亦未修正，公約要求締約國不因宗教等事由予以歧視，選項(D)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SW-104-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。本題考兒童權利公約之四項一般性原則（第2條禁止歧視、第3條兒童最佳利益、第6條生命權、生存及發展權、第12條尊重兒童意見），屬公約本文及聯合國兒童權利委員會之解釋，公約前開條文未經修正；兒童權利公約施行法第2條（公約具國內法律之效力）自 2014-11-20 施行後亦未修正，選項(B)①②④⑤仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SW-107-1-16','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考身心障礙者權利公約第2條（通用設計不排除於必要情況下為特定身心障礙者群體提供輔助用具）、第3條（尊重差異，接受身心障礙者是人之多元性之一部分）、第7條（所有關於身心障礙兒童之行動，應以兒童最佳利益為首要考量）及第13條（促進對司法領域工作人員包括警察與監所人員之培訓），屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）施行後亦未修正，選項(C)「整體家庭最佳利益」仍不符公約。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SW-112-2-05','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-07-29。本題考兒童權利公約之四項一般性原則（第2條禁止歧視、第3條兒童最佳利益、第6條生命權、生存及發展權、第12條尊重兒童意見），屬公約本文及聯合國兒童權利委員會之解釋，公約前開條文未經修正；兒童權利公約施行法第2條（公約具國內法律之效力）自 2014-11-20 施行後亦未修正，「尊重父母指導權」（第5條）非一般性原則，選項(A)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050193'),('SW-115-1-04','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-02-07。本題考經濟社會文化權利國際公約第9條（人人有權享受社會保障，包括社會保險），屬公約本文，未經修正；公民與政治權利國際公約及經濟社會文化權利國際公約施行法第2條（兩公約具國內法律之效力）施行後亦未修正，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=I0020028');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>19 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>19 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'a990f555065f587c5f9bd0e6e096fdaa' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_19, count(*) FILTER (WHERE q.legal_status='changed') changed_0, count(*) total_19 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
